#include "Verify.h"
#include <set>
using namespace strandblock;
struct Run {State state;Trace trace;bool qualified=true;unsigned phases=0;double totalMs=0;};
static std::vector<std::pair<double,double>> tolerances(bool primary){return primary?std::vector<std::pair<double,double>>{{1e-11,1e-9},{1e-12,1e-10},{1e-14,1e-13}}:std::vector<std::pair<double,double>>{{1e-11,1e-9},{1e-13,1e-11}};}
template<class Backend>static Run run(const Problem& p,bool primary,bool trace){Run r;r.state=p.initial;r.trace.enabled=trace;auto begin=Clock::now();for(auto [ptol,qtol]:tolerances(primary)){r.trace.phase=r.phases++;auto result=minimizeTraced<Backend>(p.cpu,r.state,p.dy,p.set,ptol,qtol,r.trace);r.qualified&=result.qualified;if(!result.qualified)break;}r.totalMs=ms(begin);return r;}
static State original(const Problem& p,bool primary,std::vector<ReferenceResult>& phases){auto s=p.initial;for(auto [ptol,qtol]:tolerances(primary)){auto r=autonomous::minimize(p.cpu,s,p.dy,p.set,ptol,qtol);phases.push_back(r);if(!r.qualified)break;}return s;}
static std::string energyMetrics(const Problem& p,const State& s,const State& ref){auto e=windowmath::measure(p.cpu,s,p.y,p.set);std::ostringstream o;o.precision(17);o<<"{\"F\":"<<e.total()<<",\"positionRMS\":"<<rms(s,ref)<<",\"positionMax\":"<<maxPosition(s,ref)<<",\"tipDisplacement\":"<<vectorJSON(s.x.back()-p.preX.back())<<",\"positionCorrection\":"<<e.correction<<",\"qStationarity\":"<<e.stationarity<<",\"qSpectral\":"<<e.spectral<<",\"qMaxAngle\":"<<maxAngle(s,ref)<<'}';return o.str();}
static std::string workJSON(const Work& w){std::ostringstream o;o.precision(17);o<<"{\"assemblies\":"<<w.assemblies<<",\"factors\":"<<w.factors<<",\"residualRows\":"<<w.rows<<",\"rowPairs\":"<<w.pairs<<",\"storedRowPairs\":"<<w.storedPairs<<",\"factorMultiplySubtracts\":"<<w.factorMultiplySubtracts<<",\"pivots\":"<<w.pivots<<",\"factorFailures\":"<<w.factorFailures<<",\"peakMatrixBytes\":"<<w.peakMatrixBytes<<",\"peakLinearPayloadBytes\":"<<w.peakLinearPayloadBytes<<",\"assemblyMs\":"<<w.assemblyMs<<",\"factorMs\":"<<w.factorMs<<'}';return o.str();}
static void writeRun(const fs::path& out,const std::string& name,const Problem& p,const Run& r,const State& ref){
    fs::create_directories(out/name);std::ostringstream o;o.precision(17);o<<"{\"qualified\":"<<(r.qualified?"true":"false")<<",\"acceptedIterations\":"<<r.trace.accepted<<",\"phases\":"<<r.phases<<",\"trials\":"<<r.trace.trials<<",\"rejectedTrials\":"<<r.trace.rejected<<",\"factorFailure\":"<<(r.trace.factorFailure?"true":"false")<<",\"noAcceptedTrial\":"<<(r.trace.noAcceptedTrial?"true":"false")<<",\"final\":"<<energyMetrics(p,r.state,ref)<<",\"work\":"<<workJSON(r.trace.work)<<",\"trajectory\":[";
    bool first=true;unsigned k=0;for(auto& x:r.trace.points){if(!first)o<<',';first=false;o<<"{\"phase\":"<<x.phase<<",\"phaseIteration\":"<<x.iteration<<",\"acceptedTotal\":"<<x.total<<",\"lambda\":"<<x.lambda<<",\"metrics\":"<<energyMetrics(p,x.state,ref)<<'}';writeState(out/name/("point-"+std::to_string(k++)+".json"),x.state);}o<<"],\"requestedCheckpoints\":[";first=true;
    for(unsigned wanted:{1u,2u,4u,8u,16u}){if(!first)o<<',';first=false;auto found=std::find_if(r.trace.points.begin(),r.trace.points.end(),[&](auto& x){return x.total==wanted;});o<<"{\"iteration\":"<<wanted<<",\"executed\":"<<(found!=r.trace.points.end()?"true":"false");if(found!=r.trace.points.end())o<<",\"metrics\":"<<energyMetrics(p,found->state,ref);else o<<",\"reason\":\"stopped at qualified tolerance or explicit failure before this checkpoint\"";o<<'}';}o<<"]}";text(out/name/"trace.json",o.str());writeState(out/name/"final.json",r.state);
    std::ofstream f(out/name/"trials.csv");f.precision(17);f<<"phase,iteration,retry,line,lambda,alpha,Fbefore,Ftrial,accepted\n";for(auto& t:r.trace.trialLog)f<<t.phase<<','<<t.iteration<<','<<t.retry<<','<<t.line<<','<<t.lambda<<','<<std::ldexp(1.,-int(t.line))<<','<<t.before<<','<<t.after<<','<<t.accepted<<'\n';
}
static std::string differenceJSON(StepDifference d){std::ostringstream o;o.precision(17);o<<"{\"scaledRelative\":"<<d.scaledRelative<<",\"maxPositionDifference\":"<<d.position<<",\"maxAngleDifference\":"<<d.angle<<'}';return o.str();}
static std::string linearJSON(const LinearRecord& r){std::ostringstream o;o.precision(17);o<<"{\"label\":\""<<r.label<<"\",\"n\":"<<r.n<<",\"stations\":"<<r.stations<<",\"maxBlockSize\":"<<r.maxBlock<<",\"rowStationSpan\":"<<r.rowSpan<<",\"lambda\":"<<r.lambda<<",\"offBandMax\":"<<r.offBand<<",\"offBandScaledMax\":"<<r.offBandScaled<<",\"matrixDifference\":"<<r.matrixDifference<<",\"rhsDifference\":"<<r.rhsDifference<<",\"referenceOK\":"<<(r.referenceOK?"true":"false")<<",\"blockOK\":"<<(r.blockOK?"true":"false")<<",\"qrOK\":"<<(r.qrOK?"true":"false")<<",\"referenceBackward\":"<<r.backRef<<",\"blockBackward\":"<<r.backBlock<<",\"qrBackward\":"<<r.backQR<<",\"qrAugmentedBackward\":"<<r.qrAugmentedBackward<<",\"blockIncrementDifference\":"<<differenceJSON(r.block)<<",\"QRIncrementDifference\":"<<differenceJSON(r.qr)<<",\"predictedReductionReference\":"<<r.predRef<<",\"predictedReductionBlock\":"<<r.predBlock<<",\"predictedReductionQR\":"<<r.predQR<<",\"alphaReference\":"<<r.alphaRef<<",\"alphaBlock\":"<<r.alphaBlock<<",\"acceptedEnergyReference\":"<<r.trialRef<<",\"acceptedEnergyBlock\":"<<r.trialBlock<<",\"pass\":"<<(r.pass?"true":"false")<<'}';return o.str();}
static double quantile(std::vector<double> x,double fraction){std::sort(x.begin(),x.end());return x[size_t(std::ceil(fraction*x.size()))-1];}
static void timing(const Problem& p,bool primary,const fs::path& out,const Run& expected){
    constexpr unsigned warmup=3,samples=21;for(unsigned j=0;j<warmup;j++){run<ReferenceBackend>(p,primary,false);run<BlockBackend>(p,primary,false);auto s=p.initial;for(unsigned k=0;k<32;k++)windowmath::uncachedSweep(p.cpu,s,p.y,p.set);}
    std::array<std::vector<double>,3>a,b;std::vector<double> seq;std::vector<Work> aw,bw;
    for(unsigned j=0;j<samples;j++){Run ra,rb;if(j%2){rb=run<BlockBackend>(p,primary,false);ra=run<ReferenceBackend>(p,primary,false);}else{ra=run<ReferenceBackend>(p,primary,false);rb=run<BlockBackend>(p,primary,false);}
        require(rms(ra.state,expected.state)<1e-12,"Timed baseline changed");require(ra.qualified==expected.qualified,"Timed baseline qualification changed");
        for(unsigned k=0;k<3;k++){a[k].push_back(k==0?ra.totalMs:k==1?ra.trace.work.assemblyMs:ra.trace.work.factorMs);b[k].push_back(k==0?rb.totalMs:k==1?rb.trace.work.assemblyMs:rb.trace.work.factorMs);}aw.push_back(ra.trace.work);bw.push_back(rb.trace.work);
        auto state=p.initial;auto t=Clock::now();for(unsigned n=0;n<32;n++)windowmath::uncachedSweep(p.cpu,state,p.y,p.set);seq.push_back(ms(t));
    }
    std::ostringstream o;o.precision(17);o<<"{\"warmup\":3,\"samples\":21,\"units\":\"CPU wall milliseconds; logging disabled\",\"referenceMedian\":[";for(unsigned k=0;k<3;k++){if(k)o<<',';o<<quantile(a[k],.5);}o<<"],\"blockMedian\":[";for(unsigned k=0;k<3;k++){if(k)o<<',';o<<quantile(b[k],.5);}o<<"],\"referenceP95\":[";for(unsigned k=0;k<3;k++){if(k)o<<',';o<<quantile(a[k],.95);}o<<"],\"blockP95\":[";for(unsigned k=0;k<3;k++){if(k)o<<',';o<<quantile(b[k],.95);}o<<"],\"sequential32MedianMs\":"<<quantile(seq,.5)<<",\"sequential32P95Ms\":"<<quantile(seq,.95)<<",\"referenceWork\":"<<workJSON(aw[0])<<",\"blockWork\":"<<workJSON(bw[0])<<",\"rawSamples\":[";
    for(unsigned j=0;j<samples;j++){if(j)o<<',';o<<"{\"reference\":["<<a[0][j]<<','<<a[1][j]<<','<<a[2][j]<<"],\"block\":["<<b[0][j]<<','<<b[1][j]<<','<<b[2][j]<<"],\"sequential32\":"<<seq[j]<<'}';}o<<"]}";text(out/"timing.json",o.str());
}
int main(int argc,char** argv){try{
    fs::path inputs,out,prior;bool measure=true;for(int k=1;k<argc;k++){std::string a=argv[k];require(k+1<argc,"Missing option");std::string v=argv[++k];if(a=="--inputs")inputs=v;else if(a=="--out")out=v;else if(a=="--prior-joint")prior=v;else if(a=="--timing")measure=v=="yes";else throw std::runtime_error("Unknown option");}require(!inputs.empty()&&!out.empty(),"Inputs/output required");fs::create_directories(out);
    std::vector<fs::path> files;for(auto& f:fs::directory_iterator(inputs))if(f.path().extension()==".jwp")files.push_back(f.path());std::sort(files.begin(),files.end());bool all=true;
    for(auto file:files){auto name=file.stem().string();auto p=loadProblem(file);bool primary=name=="primary";auto dest=out/name;fs::create_directories(dest);std::vector<ReferenceResult> originalPhases;auto s=original(*p,primary,originalPhases);auto dense=run<ReferenceBackend>(*p,primary,true);auto block=run<BlockBackend>(*p,primary,true);
        bool originalQualified=std::all_of(originalPhases.begin(),originalPhases.end(),[](auto& phase){return phase.qualified;});
        bool referenceReproduced=originalPhases.size()==dense.phases&&rms(s,dense.state)<1e-12&&originalQualified==dense.qualified;
        require(referenceReproduced,"Instrumented reference failed to reproduce original");
        const State& comparison=p->qualified?p->reference:dense.state;writeRun(dest,"reference",*p,dense,comparison);writeRun(dest,"block",*p,block,comparison);
        std::vector<LinearRecord> linear;linear.push_back(verifyLinear(*p,p->initial,1e-8,"original initial"));
        auto saved=p->initial;for(unsigned j=0;j<32;j++)windowmath::uncachedSweep(p->cpu,saved,p->y,p->set);linear.push_back(verifyLinear(*p,saved,1e-8,"preserved sequential32"));
        std::set<unsigned> selected{0,1,2,4,8,16,dense.trace.accepted};std::set<std::pair<unsigned,unsigned>> seen;
        for(auto& x:dense.trace.points)if(selected.count(x.total)&&seen.insert({x.phase,x.iteration}).second)linear.push_back(verifyLinear(*p,x.state,x.lambda,"reference phase"+std::to_string(x.phase)+" iter"+std::to_string(x.iteration)));
        bool linearOK=std::all_of(linear.begin(),linear.end(),[](auto& x){return x.pass;});
        std::ostringstream l;l<<'[';for(unsigned j=0;j<linear.size();j++){if(j)l<<',';l<<linearJSON(linear[j]);}l<<']';text(dest/"linear-equivalence.json",l.str());
        double pos=rms(dense.state,block.state),max=maxPosition(dense.state,block.state);
        double fd=windowmath::measure(p->cpu,dense.state,p->y,p->set).total(),fb=windowmath::measure(p->cpu,block.state,p->y,p->set).total();
        bool nonlinearOK=dense.qualified==block.qualified&&max<1e-7&&std::abs(fd-fb)<=1e-20+1e-10*std::abs(fd);
        std::ostringstream status;status.precision(17);status<<"{\"sourceId\":"<<p->id<<",\"vertices\":"<<p->initial.x.size()<<",\"freeDOFs\":"<<Layout(p->cpu,p->set).size<<",\"referenceReproduced\":true,\"linearPass\":"<<(linearOK?"true":"false")<<",\"nonlinearPass\":"<<(nonlinearOK?"true":"false")<<",\"nonlinearRMSDifference\":"<<pos<<",\"nonlinearMaxDifference\":"<<max<<",\"referenceAccepted\":"<<dense.trace.accepted<<",\"blockAccepted\":"<<block.trace.accepted<<",\"referenceRejectedTrials\":"<<dense.trace.rejected<<",\"blockRejectedTrials\":"<<block.trace.rejected<<",\"historicalReferenceQualified\":"<<(p->qualified?"true":"false")<<'}';text(dest/"status.json",status.str());
        if(measure)timing(*p,primary,dest,dense);all&=linearOK&&nonlinearOK;std::cout<<name<<" linear="<<linearOK<<" nonlinear="<<nonlinearOK<<" iterations="<<dense.trace.accepted<<'/'<<block.trace.accepted<<'\n'<<std::flush;
    }
    auto rank=loadProblem(inputs/"synthetic-2-pins0.jwp");auto state=windowmath::rest(rank->cpu);auto check=verifyLinear(*rank,state,0,"exact zero-lambda twist null mode");require(!check.referenceOK&&!check.blockOK,"Rank-deficient test must fail explicitly");text(out/"rank-deficient.json",linearJSON(check));
    return all?0:1;
}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 2;}}
